func hasExtraWorkoutDetails(w *database.Workout) bool {
	if w.Type.IsDistance() && w.Type.IsDuration() {
		return true
	}

	if w.HasPower() {
		return true
	}

	if w.Type.IsLocation() && w.HasElevation() {
		return true
	}

	return w.Type.IsDuration() && w.PauseDuration() > 0
}

